const sourceDrafts=new Map(),sourceFocus=new Map();
function preserveSourceEdits(){const app=document.getElementById('app'),key=app?.dataset.editScope;if(!key)return;const values={};for(const selector of ['#content-title','#content-body','#content-media','#library-search','#unified-content-form input','#unified-content-form textarea'])for(const input of app.querySelectorAll(selector)){values[input.id||'cloud:'+input.name]=input.value;}sourceDrafts.set(key,{...(sourceDrafts.get(key)||{}),...values});const active=document.activeElement;if(active?.matches('#content-title,#content-body,#content-media,#library-search,#unified-content-form input,#unified-content-form textarea,#unified-payload-title,#unified-payload-body,#unified-payload-tags,#unified-payload-author'))sourceFocus.set(key,{id:active.id,name:active.name,start:active.selectionStart,end:active.selectionEnd});}
function restoreSourceEdits(){const app=document.getElementById('app'),values=sourceDrafts.get(app?.dataset.editScope)||{};for(const selector of ['#content-title','#content-body','#content-media','#library-search','#unified-content-form input','#unified-content-form textarea'])for(const input of app.querySelectorAll(selector)){const key=input.id||'cloud:'+input.name;if(Object.hasOwn(values,key))input.value=values[key];}const focus=sourceFocus.get(app?.dataset.editScope),input=focus&&(focus.id?document.getElementById(focus.id):[...app.querySelectorAll('#unified-content-form input,#unified-content-form textarea')].find(x=>x.name===focus.name));if(input&&(!document.activeElement||document.activeElement===document.body)){input.focus();if(typeof focus.start==='number')input.setSelectionRange(focus.start,focus.end);}}
