function restoreGroupSelection(){if(route!=='groups')return;const account=selectedFacebookAccount();if(!account)return;let ids=[];try{ids=JSON.parse(sessionStorage.getItem(groupSelectionKey(account.id))||'[]')}catch{}if(!Array.isArray(ids))ids=[];const allowed=new Set(fb.facebookGroups.filter(g=>g.account_id===account.id&&g.enabled&&g.membership_status==='JOINED').map(g=>g.id));replaceGroupSelection(document.querySelectorAll('.group-list [data-group]'),ids.filter(id=>allowed.has(id)))}
function groupFilters(accountId){try{const saved=JSON.parse(localStorage.getItem(groupFilterKey(accountId))||'null');return saved&&typeof saved==='object'?{include:String(saved.include||''),exclude:String(saved.exclude||'')}:{include:'',exclude:''}}catch{return {include:'',exclude:''}}}
function activeGroupFilters(){const account=selectedFacebookAccount();return account?{include:document.getElementById('group-name-include')?.value??groupFilters(account.id).include,exclude:document.getElementById('group-name-exclude')?.value??groupFilters(account.id).exclude}:{include:'',exclude:''}}
function applyGroupFilters(){const account=selectedFacebookAccount();if(!account)return;const filters=activeGroupFilters();localStorage.setItem(groupFilterKey(account.id),JSON.stringify(filters));let shown=0,selected=0;document.querySelectorAll('.group-list [data-group]').forEach(input=>{const group=fb.facebookGroups.find(g=>g.id===input.dataset.group),visible=Boolean(group&&groupNameMatches(group.name,filters));input.closest('label').hidden=!visible;if(!visible)input.checked=false;if(visible)shown++;if(input.checked)selected++});if(route==='groups')sessionStorage.setItem(groupSelectionKey(account.id),JSON.stringify([...document.querySelectorAll('.group-list [data-group]:checked')].map(input=>input.dataset.group)));const count=document.getElementById('selected-count');if(count)count.textContent=`已选择 ${selected} 个 · 当前显示 ${shown} 个`;const summary=document.getElementById('group-filter-summary');if(summary)summary.textContent=`群组名筛选后显示 ${shown} / ${fb.facebookGroups.filter(g=>g.account_id===account.id).length} 个；排除词不会进入本次任务。`;document.querySelectorAll('[data-prepare]').forEach(button=>{const job=fb.groupJobs.find(j=>j.id===button.dataset.prepare),group=fb.facebookGroups.find(g=>g.id===job?.group_id),excluded=!groupNameMatches(group?.name,filters);button.disabled=excluded||(core?.pageExecutionEnabled===true&&!fb?.scopedExecution?.supported);button.textContent=excluded?'当前筛选已排除':core?.pageExecutionEnabled&&!fb?.scopedExecution?.supported?'群组提交未开放':'核对并单次发布此任务'})}
