    if(job.post_url&&!cell.querySelector('[data-claim]'))cell.insertAdjacentHTML('beforeend',`<input data-claim-input="${esc(job.id)}" value="${esc(job.post_url)}" placeholder="帖子链接"><button data-claim="${esc(job.id)}">核对平台</button>`);
