  if(by('random-select-groups'))by('random-select-groups').onclick=()=>{try{const account=selectedFacebookAccount();const ids=randomGroupIds(fb.facebookGroups,account.id,Number(by('random-group-count').value),activeGroupFilters());replaceGroupSelection(document.querySelectorAll('.group-list [data-group]'),ids);applyGroupFilters();const status=by('group-task-status');if(status)status.textContent=ids.length?'已重新随机选择 '+ids.length+' 个群组，本轮选择已替换；创建任务后自动清空。':'当前筛选没有可用群组，已清空上轮选择。';}catch(e){const status=by('group-task-status');if(status)status.textContent=e.message;}};
