  if(by('create-jobs')){by('create-jobs').textContent='创建并自动发布';by('create-jobs').onclick=()=>createGroupTasks(by('create-jobs'),true);const manual=document.createElement('button');manual.id='create-only';manual.textContent='仅创建任务';manual.onclick=()=>createGroupTasks(manual,false);by('create-jobs').before(manual)}
  document.querySelectorAll('[data-prepare]').forEach(button=>{button.onclick=async()=>{button.disabled=true;try{const filters=activeGroupFilters();if(fb.scopedExecution?.supported){const selectedWorkspace=workspace,selectedAccount=selectedFacebookAccount()?.id,id=button.dataset.prepare;const result=await confirmScopedAction({readCapability:()=>request(`/api/workspaces/${selectedWorkspace}/group-jobs/${id}/execution-capability`,{}),submit:confirmation=>request(`/api/workspaces/${selectedWorkspace}/group-jobs/auto-publish`,{job_ids:[id],...confirmation}),isCurrent:()=>workspace===selectedWorkspace&&selectedFacebookAccount()?.id===selectedAccount});if(!result)return;}else await request(`/api/workspaces/${workspace}/group-jobs/auto-publish`,{job_ids:[button.dataset.prepare],group_name_include:filters.include,group_name_exclude:filters.exclude});message='已启动自动发布，系统正在核对身份、提交并回读帖子链接';await load();scheduleGroupRefresh([button.dataset.prepare])}catch(e){message=e.message;await load()}finally{if(button.isConnected)button.disabled=false}}});
