function ensureAccountDefaults(){
  if(core?.unified&&route==='settings'){
    const transport=document.getElementById('account-execution-transport');
    if(transport){transport.value='BROWSER';transport.disabled=true;}
  }
  if(route!=='settings'||!fb)return;
  const field=document.getElementById('account-id'),account=fb.accounts.find(x=>x.id===fb.selectedAccountId);
  if(!field||!account||field.dataset.editing==='true'||field.dataset.prefilled===account.id)return;
  field.value=account.id;
  document.getElementById('account-name').value=account.display_name;
  document.getElementById('expected').value=account.expected_identity;
  document.getElementById('identity-type').value=account.identity_type;
  document.getElementById('profile-id').value=account.profile_id;
  document.getElementById('account-external-id').value=account.operator_actor_id||account.external_id||'';document.getElementById('account-target-page-id').value=account.target_page_id||'';
  document.getElementById('account-external-id').placeholder='Facebook 个人账号或 Page 的数字 ID';
  document.getElementById('account-config-url').value=account.config_url||'';
  document.getElementById('account-execution-transport').value=core?.unified?'BROWSER':(account.execution_transport||(account.api_enabled?'API':'BROWSER'));
  if(core?.unified)document.getElementById('account-execution-transport').disabled=true;
  field.dataset.prefilled=account.id;
  const label=document.getElementById('account-external-id')?.closest('label');
  if(label)label.firstChild.textContent='Facebook 操作 actor ID（核对后确认）';
}
